<?php
namespace Tests\Feature;
use App\Enums\UserRole;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class AuthorizationMatrixTest extends TestCase{use RefreshDatabase;
 public function test_role_matrix_for_patient_staff_and_power_admin_surfaces():void{$staffDenied=['/api/staff/dashboard'=>403,'/api/staff/calendar?from=2026-08-01&to=2026-08-02'=>403];$staffAllowed=['/api/staff/dashboard'=>200,'/api/staff/calendar?from=2026-08-01&to=2026-08-02'=>200];$cmsDenied=['/api/cms/pages'=>403,'/api/cms/verification-queue'=>403,'/api/cms/audit-logs'=>403];$cmsAllowed=['/api/cms/pages'=>200,'/api/cms/verification-queue'=>200,'/api/cms/audit-logs'=>200];$matrix=[[UserRole::Patient,['/api/me/profile'=>200]+$staffDenied+$cmsDenied],[UserRole::Moderator,['/api/me/profile'=>403]+$staffAllowed+$cmsDenied],[UserRole::Admin,['/api/me/profile'=>403]+$staffAllowed+$cmsDenied],[UserRole::PowerAdmin,['/api/me/profile'=>403]+$staffAllowed+$cmsAllowed]];foreach($matrix as[$role,$routes]){Sanctum::actingAs(User::factory()->create(['role'=>$role]));foreach($routes as$route=>$expected)$this->getJson($route)->assertStatus($expected,"{$role->value} access mismatch for {$route}");}}
 public function test_inactive_accounts_are_rejected_from_every_protected_surface():void{Sanctum::actingAs(User::factory()->create(['role'=>UserRole::PowerAdmin,'is_active'=>false]));foreach(['/api/me','/api/staff/dashboard','/api/cms/pages']as$route)$this->getJson($route)->assertForbidden();}
 public function test_unverified_accounts_reach_identity_but_not_private_patient_or_cms_data():void{Sanctum::actingAs(User::factory()->unverified()->create());$this->getJson('/api/me')->assertOk();$this->getJson('/api/me/profile')->assertForbidden();Sanctum::actingAs(User::factory()->unverified()->create(['role'=>UserRole::PowerAdmin]));$this->getJson('/api/staff/dashboard')->assertOk();$this->getJson('/api/cms/pages')->assertForbidden();}
}
